const requiredLocales = ['de','en','fr','es','it','nl','pl','pt-BR','tr','cs','da','sv','nb','fi','ro','hu','el','uk','ru','ar','zh-CN','zh-TW','ja','ko'];
for (const locale of requiredLocales) {
  if (!values[locale] || values[locale].length !== RECORDING_STORAGE_MESSAGE_KEYS.length) throw new Error(`Incomplete recording storage translations: ${locale}`);
}

export const recordingStorageMessages = Object.fromEntries(
  Object.entries(values).map(([locale, translations]) => [locale, Object.fromEntries(RECORDING_STORAGE_MESSAGE_KEYS.map((key, index) => [key, translations[index]]))]),
);
